list_inventory_locations.code:
const response = await client.inventoryLocations.listInventoryLocations({q: 'Sydney'});
for (const inventoryLocation of response.map.inventory_locations) {
    console.log(inventoryLocation.id, inventoryLocation.name, inventoryLocation.is_default);
}

create_inventory_location.code:
const response = await client.inventoryLocations.createInventoryLocation({
    name: 'Perth Warehouse',
    address: '4 Example Street, Perth WA 6000',
});
console.log(response.map.inventory_location.id, response.map.inventory_location.is_active);

get_inventory_location.code:
const response = await client.inventoryLocations.getInventoryLocation(4);
const inventoryLocation = response.map.inventory_location;
console.log(inventoryLocation.name, inventoryLocation.address, inventoryLocation.is_active);

update_inventory_location.code:
const response = await client.inventoryLocations.updateInventoryLocation(19, {
    name: 'Perth Warehouse',
    address: '10 Example Street, Perth WA 6000',
    is_active: true,
    is_default: false,
});
const inventoryLocation = response.map.inventory_location;
console.log(inventoryLocation.address, inventoryLocation.is_active, inventoryLocation.is_default);

get_inventory_location_stock.code:
const response = await client.inventoryLocations.getInventoryLocationStock(4);
for (const product of response.map.products) {
    console.log(product.product_id, product.name, product.stock);
